// Swift's cross-module inlining: expose the body to the client's optimiser.
// @inlinable is NOT for most functions (code size, ABI commitment); use it for
// small cross-module helpers and generic witnesses.
@inlinable
public func clampAdd(_ a: Int, _ b: Int, _ limit: Int) -> Int {
    let s = a + b
    return s > limit ? limit : s
}

// @_transparent substitutes the body at the call site (stdlib-internal, underscored)
@_transparent
internal func _min(_ a: Int, _ b: Int) -> Int { a < b ? a : b }

